:root {
  --card-bg: #fffdf4;
  --header-bg: #3a7d44;
  --header-text: #ffffff;
  --badge-bg: #f4c430;
  --badge-text: #5a3e00;
  --stamp-filled-bg: #e8f5e9;
  --stamp-filled-border: #3a7d44;
  --stamp-empty-bg: #f0ece0;
  --stamp-empty-border: #c8bfa0;
  --footer-bg: #f2efe3;
  --progress-track: #ddd8c4;
  --progress-fill: #3a7d44;
  --footer-text: #5a5240;
  --reward-text: #3a7d44;
  --card-border: #c8bfa0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.stamp-card {
  background: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 16px;
  width: 420px;
  overflow: hidden;
}

.card-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
}

.card-icon {
  font-size: 28px;
  line-height: 1;
}

.card-title h2 {
  color: var(--header-text);
  font-size: 16px;
  font-weight: 700;
  margin: 0;
  line-height: 1.2;
}

.card-title p {
  color: var(--header-text);
  font-size: 11px;
  margin: 0;
  opacity: 0.85;
}

.card-badge {
  margin-left: auto;
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 20px;
  letter-spacing: 0.08em;
}

.stamp-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
  padding: 14px 16px;
}

.stamp {
  aspect-ratio: 1;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  border: 2px dashed var(--stamp-empty-border);
  background: var(--stamp-empty-bg);
}

.stamp.stamped {
  background: var(--stamp-filled-bg);
  border: 2px solid var(--stamp-filled-border);
}

.stamp.empty {
  background: var(--stamp-empty-bg);
  border: 2px dashed var(--stamp-empty-border);
}

.card-footer {
  background: var(--footer-bg);
  padding: 10px 16px 12px;
  display: flex;
  align-items: center;
  gap: 10px;
  border-top: 1px solid var(--card-border);
}

.progress-label {
  color: var(--footer-text);
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}

.progress-bar {
  flex: 1;
  height: 8px;
  background: var(--progress-track);
  border-radius: 999px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 80%;
  background: var(--progress-fill);
  border-radius: 999px;
}

.reward-label {
  color: var(--reward-text);
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}
